import{_ as c,C as p,o as r,c as o,j as a,a as e,E as n,a2 as t,w as h}from"./chunks/framework.B-bxTAy7.js";const b=JSON.parse('{"title":"08 · 数电接口：AD/DA 与脉冲调制","description":"","frontmatter":{"title":"08 · 数电接口：AD/DA 与脉冲调制"},"headers":[],"relativePath":"digital/ad-da.md","filePath":"digital/ad-da.md","lastUpdated":1792474335000}'),g={name:"digital/ad-da.md"};function x(d,s,w,u,y,k){const l=p("Meta"),m=p("AdcDemo"),i=p("DemoBox");return r(),o("div",null,[s[3]||(s[3]=a("h1",{id:"_08-·-数电接口-ad-da-与脉冲调制",tabindex:"-1"},[e("08 · 数电接口：AD/DA 与脉冲调制 "),a("a",{class:"header-anchor",href:"#_08-·-数电接口-ad-da-与脉冲调制","aria-label":'Permalink to "08 · 数电接口：AD/DA 与脉冲调制"'},"​")],-1)),n(l,{time:"45 min",level:"核心",note:"采样定理、量化误差、DAC/ADC 四大结构、PWM——模拟世界与数字世界的最后一道桥"}),s[4]||(s[4]=t(`<h2 id="结论先行" tabindex="-1">结论先行 <a class="header-anchor" href="#结论先行" aria-label="Permalink to &quot;结论先行&quot;">​</a></h2><ol><li><strong>现实世界是模拟的，数字系统只认 0/1</strong>，ADC 与 DAC 就是两界之间的桥。转换链条固定：<strong>采样（时域离散）→ 保持 → 量化（幅度离散）→ 编码</strong>。</li><li><strong>采样定理</strong>：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>f</mi><mi>s</mi></msub><mo>≥</mo><mn>2</mn><msub><mi>f</mi><mi>max</mi><mo>⁡</mo></msub></mrow><annotation encoding="application/x-tex">f_s\\ge2f_{\\max}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≥</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord">2</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mop mtight"><span class="mtight">m</span><span class="mtight">a</span><span class="mtight">x</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 才能完整重建；采样不足会产生<strong>混叠</strong>——高频信号伪装成低频，一旦发生就无法在后端挽回，必须在采样前用抗混叠滤波器挡住。</li><li><strong>DAC 两大经典结构</strong>：权电阻网络直观但电阻档位多；<strong>R-2R 梯形网络只用两种阻值</strong>，是主流。指标看分辨率（位数）、建立时间、线性度。</li><li><strong>ADC 四大类</strong>：并行比较（快而贵）、<strong>逐次逼近 SAR（速度价格折中，MCU 内置主流）</strong>、双积分（慢而抗干扰，数字电压表）、计数式（最慢已淘汰）。</li><li><strong>量化误差不可避免</strong>：理想 ADC 误差 ≤ ±½ LSB，位数每多 1 位，误差减半、数据量翻倍——精度与成本的交换。</li><li><strong>PWM</strong> 用通断比例等效出电压：等效值 = 占空比 × 高电平；配低通滤波得模拟量。开关管两态工作损耗小，是调光、调速、开关电源的基石。</li></ol><h2 id="推导脉络-一个模拟量怎么变成一串数字" tabindex="-1">推导脉络：一个模拟量怎么变成一串数字 <a class="header-anchor" href="#推导脉络-一个模拟量怎么变成一串数字" aria-label="Permalink to &quot;推导脉络：一个模拟量怎么变成一串数字&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>温度/声音/电压（连续）</span></span>
<span class="line"><span>   │  ① 采样：按 fs 周期性取值        ← 采样定理在这里把关</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>一串离散的样点（幅度还是连续的）</span></span>
<span class="line"><span>   │  ② 保持：样值稳住，等量化</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>   │  ③ 量化：幅度归到邻近的电平栅格  ← 误差在这里产生</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>   │  ④ 编码：电平编号写成二进制</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>数字码流 ──► 数字系统处理 ──► DAC ──► 模拟世界</span></span></code></pre></div><p>注意②③的次序不可换：不保持的话，量化还没做完样值就变了。而<strong>采样定理是整条链的入口门槛</strong>——进来时丢了的信息，后面任何处理都变不回来。</p><h2 id="图解1-采样、量化与混叠" tabindex="-1">图解①：采样、量化与混叠 <a class="header-anchor" href="#图解1-采样、量化与混叠" aria-label="Permalink to &quot;图解①：采样、量化与混叠&quot;">​</a></h2>`,6)),n(i,{title:"采样定理：低于 2 倍频就看到假信号",hint:"把采样频率拖到输入频率 2 倍以下，红色混叠波立刻出现；再拖回 2 倍以上看它消失。位数滑块管的是量化栅格的粗细。"},{default:h(()=>[n(m)]),_:1}),s[5]||(s[5]=t('<p>三个滑块就是整条链的三个参数。把「采样频率」拖到低于输入频率的 2 倍，红色虚线会冒出来——<strong>它才是采样后系统以为的真实信号</strong>，频率低得多、波形像得多，这就是混叠的阴险之处：看起来毫无异常。位数滑块则控制量化栅格的粗细，位数越少阶梯越粗。</p><h2 id="图解2-dac-重建与-pwm" tabindex="-1">图解②：DAC 重建与 PWM <a class="header-anchor" href="#图解2-dac-重建与-pwm" aria-label="Permalink to &quot;图解②：DAC 重建与 PWM&quot;">​</a></h2><p>切到「DAC 重建」页签，点比特按钮改码值，看阶梯输出怎么跟着变——输出电压 = 码值 / <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>2</mn><mi>N</mi></msup></mrow><annotation encoding="application/x-tex">2^N</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8413em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span></span></span></span></span></span></span> × 满量程。切到「PWM 调速」，拖动占空比：蓝色方波的通断比例改变，红线（经 RC 低通）稳定在不同的电压上。<strong>开关不发热地改变能量输送比例</strong>，这就是所有开关电源的祖传思想。</p><h2 id="典型例题-数字均经计算" tabindex="-1">典型例题（数字均经计算） <a class="header-anchor" href="#典型例题-数字均经计算" aria-label="Permalink to &quot;典型例题（数字均经计算）&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">例 1 · 采样定理验算</p><p>语音信号频率上限 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>4</mn><mtext> </mtext><mtext>kHz</mtext></mrow><annotation encoding="application/x-tex">4\\,\\text{kHz}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">4</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">kHz</span></span></span></span></span>，则 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>f</mi><mi>s</mi></msub><mo>≥</mo><mn>2</mn><mo>×</mo><mn>4</mn><mo>=</mo><mn>8</mn><mtext> </mtext><mtext>kHz</mtext></mrow><annotation encoding="application/x-tex">f_s\\ge2\\times4=8\\,\\text{kHz}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≥</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">8</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">kHz</span></span></span></span></span>——电话系统正是取 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>8</mn><mtext> </mtext><mtext>kHz</mtext></mrow><annotation encoding="application/x-tex">8\\,\\text{kHz}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">8</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">kHz</span></span></span></span></span>。CD 音质上限 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>20</mn><mtext> </mtext><mtext>kHz</mtext></mrow><annotation encoding="application/x-tex">20\\,\\text{kHz}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">20</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">kHz</span></span></span></span></span>，理论下限 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>40</mn><mtext> </mtext><mtext>kHz</mtext></mrow><annotation encoding="application/x-tex">40\\,\\text{kHz}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">40</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">kHz</span></span></span></span></span>，实际取 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>44.1</mn><mtext> </mtext><mtext>kHz</mtext></mrow><annotation encoding="application/x-tex">44.1\\,\\text{kHz}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">44.1</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">kHz</span></span></span></span></span>（约 2.21 倍余量），既防混叠又给滤波器过渡带留空间。若偷懒用 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>8</mn><mtext> </mtext><mtext>kHz</mtext></mrow><annotation encoding="application/x-tex">8\\,\\text{kHz}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">8</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">kHz</span></span></span></span></span> 采 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>6</mn><mtext> </mtext><mtext>kHz</mtext></mrow><annotation encoding="application/x-tex">6\\,\\text{kHz}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">6</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">kHz</span></span></span></span></span> 的信号，混叠出 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi mathvariant="normal">∣</mi><mn>8</mn><mo>−</mo><mn>6</mn><mi mathvariant="normal">∣</mi><mo>=</mo><mn>2</mn><mtext> </mtext><mtext>kHz</mtext></mrow><annotation encoding="application/x-tex">|8-6|=2\\,\\text{kHz}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∣8</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">6∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">kHz</span></span></span></span></span> 的假信号——耳朵听到的是错的东西。</p></div><div class="tip custom-block"><p class="custom-block-title">例 2 · DAC 分辨率</p><p>8 位 DAC、参考电压 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>10</mn><mtext> </mtext><mtext>V</mtext></mrow><annotation encoding="application/x-tex">10\\,\\text{V}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">10</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">V</span></span></span></span></span>：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>LSB</mtext><mo>=</mo><mn>10</mn><mi mathvariant="normal">/</mi><msup><mn>2</mn><mn>8</mn></msup><mo>=</mo><mn>39.06</mn><mtext> </mtext><mtext>mV</mtext></mrow><annotation encoding="application/x-tex">\\text{LSB}=10/2^8=39.06\\,\\text{mV}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">LSB</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord">10/</span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">8</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">39.06</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">mV</span></span></span></span></span>。输入码 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mn>10000001</mn><mn>2</mn></msub><mo>=</mo><mn>129</mn></mrow><annotation encoding="application/x-tex">10000001_2=129</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7944em;vertical-align:-0.15em;"></span><span class="mord">1000000</span><span class="mord"><span class="mord">1</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">129</span></span></span></span>，输出 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>=</mo><mn>129</mn><mo>×</mo><mn>39.06</mn><mtext> </mtext><mtext>mV</mtext><mo>≈</mo><mn>5.039</mn><mtext> </mtext><mtext>V</mtext></mrow><annotation encoding="application/x-tex">=129\\times39.06\\,\\text{mV}\\approx5.039\\,\\text{V}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.3669em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">129</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">39.06</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">mV</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">5.039</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">V</span></span></span></span></span>。满量程码 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mn>11111111</mn><mn>2</mn></msub><mo>=</mo><mn>255</mn></mrow><annotation encoding="application/x-tex">11111111_2=255</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7944em;vertical-align:-0.15em;"></span><span class="mord">1111111</span><span class="mord"><span class="mord">1</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">255</span></span></span></span> 只输出 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>9.961</mn><mtext> </mtext><mtext>V</mtext></mrow><annotation encoding="application/x-tex">9.961\\,\\text{V}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">9.961</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">V</span></span></span></span></span>（= 量程 − 1 LSB），<strong>永远到不了 10 V</strong>——这是 DAC 的固有特性，别当成故障。同量程 12 位 LSB 降到 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2.441</mn><mtext> </mtext><mtext>mV</mtext></mrow><annotation encoding="application/x-tex">2.441\\,\\text{mV}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">2.441</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">mV</span></span></span></span></span>，分辨率提升 16 倍。</p></div><div class="tip custom-block"><p class="custom-block-title">例 3 · ADC 量化误差</p><p>8 位 ADC、量程 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>0</mn><mo>∼</mo><mn>5</mn><mtext> </mtext><mtext>V</mtext></mrow><annotation encoding="application/x-tex">0\\sim5\\,\\text{V}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">V</span></span></span></span></span>，LSB <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>=</mo><mn>19.53</mn><mtext> </mtext><mtext>mV</mtext></mrow><annotation encoding="application/x-tex">=19.53\\,\\text{mV}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.3669em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">19.53</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">mV</span></span></span></span></span>。输入 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>3.300</mn><mtext> </mtext><mtext>V</mtext></mrow><annotation encoding="application/x-tex">3.300\\,\\text{V}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">3.300</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">V</span></span></span></span></span>，量化码 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>=</mo><mtext>round</mtext><mo stretchy="false">(</mo><mn>3.300</mn><mi mathvariant="normal">/</mi><mn>0.01953</mn><mo stretchy="false">)</mo><mo>=</mo><mn>169</mn><mo>=</mo><msub><mn>10101001</mn><mn>2</mn></msub></mrow><annotation encoding="application/x-tex">=\\text{round}(3.300/0.01953)=169=10101001_2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.3669em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">round</span></span><span class="mopen">(</span><span class="mord">3.300/0.01953</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">169</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7944em;vertical-align:-0.15em;"></span><span class="mord">1010100</span><span class="mord"><span class="mord">1</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，重建值 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>3.3008</mn><mtext> </mtext><mtext>V</mtext></mrow><annotation encoding="application/x-tex">3.3008\\,\\text{V}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">3.3008</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">V</span></span></span></span></span>，误差仅 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>−</mo><mn>0.8</mn><mtext> </mtext><mtext>mV</mtext></mrow><annotation encoding="application/x-tex">-0.8\\,\\text{mV}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord">0.8</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">mV</span></span></span></span></span>（≤ ½ LSB <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>=</mo><mn>9.8</mn><mtext> </mtext><mtext>mV</mtext></mrow><annotation encoding="application/x-tex">=9.8\\,\\text{mV}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.3669em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">9.8</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">mV</span></span></span></span></span>）。这次误差小是运气；最坏情况误差接近 ½ LSB，折合满量程的 0.2%。<strong>位数决定误差下限</strong>：要 0.1% 以内，至少得 10 位以上。</p></div><div class="tip custom-block"><p class="custom-block-title">例 4 · SAR 与双积分的速度账</p><p>SAR 型 8 位 ADC 每次要「采样保持 + 逐位比较 8 回」，至少 9 个时钟。时钟 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mtext> </mtext><mtext>MHz</mtext></mrow><annotation encoding="application/x-tex">1\\,\\text{MHz}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">MHz</span></span></span></span></span> 时转换时间约 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>9</mn><mtext> </mtext><mi>μ</mi><mtext>s</mtext></mrow><annotation encoding="application/x-tex">9\\,\\mu\\text{s}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">9</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">μ</span><span class="mord text"><span class="mord">s</span></span></span></span></span>，每秒可完成约 111 k 次转换——这就是 MCU 内置 ADC 的典型速度。双积分型反过来：积分时间取工频周期的整数倍（<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>20</mn><mtext> </mtext><mtext>ms</mtext></mrow><annotation encoding="application/x-tex">20\\,\\text{ms}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">20</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">ms</span></span></span></span></span> 的整数倍），<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>50</mn><mtext> </mtext><mtext>Hz</mtext></mrow><annotation encoding="application/x-tex">50\\,\\text{Hz}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">50</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">Hz</span></span></span></span></span> 干扰在一个积分周期内平均为零，抗干扰能力理论上无穷大，代价是每秒只能转几十次。<strong>要快用 SAR，要稳用双积分</strong>，数字万用表里常见后者。</p></div><h2 id="工程实例-从传感器到云端的完整链路" tabindex="-1">工程实例：从传感器到云端的完整链路 <a class="header-anchor" href="#工程实例-从传感器到云端的完整链路" aria-label="Permalink to &quot;工程实例：从传感器到云端的完整链路&quot;">​</a></h2><p>一条物联网温度链走一遍今天的所有概念：</p><ol><li><strong>NTC 热敏电阻</strong>随温度改变阻值，经分压变成电压（<a href="./../ee/01-basics/model-reference">欧姆定律与分压器</a>的老本行）；</li><li><strong>抗混叠滤波器</strong>（RC 低通）先把高频噪声挡在采样频率一半以下——没有它，噪声会混叠进有用频段；</li><li><strong>SAR ADC</strong>（MCU 内置 12 位）把电压变成码值，每秒采几千次；</li><li>MCU 算出温度，通过 <strong>PWM</strong> 控制加热器占空比做恒温——整套系统只靠「比较 + 计数 + 通断」就完成了模拟量的精确处理。</li></ol><p>反过来，播放端：存储器里的数字音频经 <strong>DAC</strong>（R-2R 或 Σ-Δ）重建为阶梯波，再经低通滤波器平滑，才到你耳朵里。<strong>你听到的每一段数字音乐，终点都是这一章的电路。</strong></p><h2 id="易错清单-自检" tabindex="-1">易错清单 + 自检 <a class="header-anchor" href="#易错清单-自检" aria-label="Permalink to &quot;易错清单 + 自检&quot;">​</a></h2>',13)),a("ul",null,[s[2]||(s[2]=t("<li><strong>混叠不可恢复</strong>：指望软件「修」混叠是徒劳，防线只有两个——提高采样率，或在 ADC 前加抗混叠低通。</li><li><strong>量化误差 ≠ 噪声的全部</strong>：还有偏置误差、增益误差、非线性（INL/DNL）。选型时别只看位数。</li><li><strong>½ LSB 是理想下限</strong>：实际 ADC 的积分/微分非线性会让有效位数（ENOB）低于标称位数， datasheet 里找 ENOB 才是诚实的做法。</li><li><strong>SAR 前必须有采样保持</strong>：比较期间输入不能变，否则高位比完低位时样值已漂移。</li><li><strong>PWM 等效电压是「平均值」概念</strong>：对惯性负载（电机、LED 视觉、加热丝）有效；对「认瞬时值」的负载（如想直接驱动运放）必须先滤波。</li>",5)),a("li",null,[s[0]||(s[0]=e("自检：在 ",-1)),n(m),s[1]||(s[1]=t(' 里把输入频率拖到 15、采样频率拖到 20（比值 1.33 &lt; 2），看红色混叠波的频率是不是 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi mathvariant="normal">∣</mi><mn>20</mn><mo>−</mo><mn>15</mn><mi mathvariant="normal">∣</mi><mo>=</mo><mn>5</mn></mrow><annotation encoding="application/x-tex">|20-15|=5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∣20</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">15∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">5</span></span></span></span>？再把采样频率拖过 30，混叠警告是否消失？这两个动作做一遍，采样定理就刻进直觉了。',3))])])])}const v=c(g,[["render",x]]);export{b as __pageData,v as default};
